class TrieNode {
    TrieNode[] children = new TrieNode[26];
    String word = null;
}

public List<String> findWords(char[][] board, String[] words) {
    TrieNode root = new TrieNode();
    for (String w : words) {
        TrieNode node = root;
        for (char c : w.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.word = w;
    }
    List<String> res = new ArrayList<>();
    for (int i = 0; i < board.length; i++)
        for (int j = 0; j < board[0].length; j++)
            dfs(board, i, j, root, res);
    return res;
}

private void dfs(char[][] board, int i, int j, TrieNode node, List<String> res) {
    char c = board[i][j];
    if (c == '#' || node.children[c - 'a'] == null) return;
    node = node.children[c - 'a'];
    if (node.word != null) {
        res.add(node.word);
        node.word = null; // dedup
    }
    board[i][j] = '#';
    if (i > 0) dfs(board, i - 1, j, node, res);
    if (i + 1 < board.length) dfs(board, i + 1, j, node, res);
    if (j > 0) dfs(board, i, j - 1, node, res);
    if (j + 1 < board[0].length) dfs(board, i, j + 1, node, res);
    board[i][j] = c;
}

class WordDictionary {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord = false;
    }
    private final TrieNode root = new TrieNode();

    public WordDictionary() {}

    public void addWord(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.isWord = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, root);
    }

    private boolean dfs(String word, int i, TrieNode node) {
        if (node == null) return false;
        if (i == word.length()) return node.isWord;
        char c = word.charAt(i);
        if (c == '.') {
            for (TrieNode child : node.children)
                if (dfs(word, i + 1, child)) return true;
            return false;
        }
        return dfs(word, i + 1, node.children[c - 'a']);
    }
}

