public int findMaximumXOR(int[] nums) {
    TrieNode root = new TrieNode();
    for (int num : nums) insert(root, num);
    int max = 0;
    for (int num : nums) max = Math.max(max, query(root, num));
    return max;
}

private void insert(TrieNode root, int num) {
    TrieNode node = root;
    for (int i = 31; i >= 0; i--) {
        int bit = (num >> i) & 1;
        if (node.children[bit] == null) node.children[bit] = new TrieNode();
        node = node.children[bit];
    }
}

private int query(TrieNode root, int num) {
    TrieNode node = root;
    int xor = 0;
    for (int i = 31; i >= 0; i--) {
        int bit = (num >> i) & 1;
        int want = 1 - bit; // prefer opposite bit to maximize XOR
        if (node.children[want] != null) {
            xor |= (1 << i);
            node = node.children[want];
        } else {
            node = node.children[bit];
        }
    }
    return xor;
}

