    TrieNode[] children = new TrieNode[26];
    boolean isWord = false;
}
private final TrieNode root = new TrieNode();

public List<String> findAllConcatenatedWordsInADict(String[] words) {
    Arrays.sort(words, (a, b) -> a.length() - b.length());
    List<String> res = new ArrayList<>();
    for (String w : words) {
        if (w.isEmpty()) continue;
        if (canForm(w)) res.add(w);
        insert(w); // insert after checking so a word never builds itself
    }
    return res;
}

private void insert(String w) {
    TrieNode node = root;
    for (char c : w.toCharArray()) {
        int idx = c - 'a';
        if (node.children[idx] == null) node.children[idx] = new TrieNode();
        node = node.children[idx];
    }
    node.isWord = true;
}

private boolean canForm(String w) {
    int n = w.length();
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 0; i < n; i++) {
        if (!dp[i]) continue;
        TrieNode node = root;
        for (int j = i; j < n; j++) {
            node = node.children[w.charAt(j) - 'a'];
            if (node == null) break;
            if (node.isWord) dp[j + 1] = true;
        }
    }
    return dp[n];
}

public List<List<Integer>> palindromePairs(String[] words) {
    Map<String, Integer> map = new HashMap<>();
    for (int i = 0; i < words.length; i++) map.put(words[i], i);
    List<List<Integer>> res = new ArrayList<>();
    for (int i = 0; i < words.length; i++) {
        String w = words[i];
        int n = w.length();
        for (int j = 0; j <= n; j++) {
            String left = w.substring(0, j);
            String right = w.substring(j);
            if (isPalindrome(left)) {
                String rev = new StringBuilder(right).reverse().toString();
                Integer k = map.get(rev);
                if (k != null && k != i) res.add(Arrays.asList(k, i));
            }
            if (j != n && isPalindrome(right)) {
                String rev = new StringBuilder(left).reverse().toString();
                Integer k = map.get(rev);
                if (k != null && k != i) res.add(Arrays.asList(i, k));
            }
        }
    }
    return res;
}

private boolean isPalindrome(String s) {
    int l = 0, r = s.length() - 1;
    while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;
    return true;
}

class StreamChecker {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord = false;
    }
    private final TrieNode root = new TrieNode();
    private final StringBuilder sb = new StringBuilder();
    private int maxLen = 0;

    public StreamChecker(String[] words) {
        for (String w : words) {
            maxLen = Math.max(maxLen, w.length());
            TrieNode node = root;
            for (int i = w.length() - 1; i >= 0; i--) {
                int idx = w.charAt(i) - 'a';
                if (node.children[idx] == null) node.children[idx] = new TrieNode();
                node = node.children[idx];
            }
            node.isWord = true;
        }
    }

    public boolean query(char letter) {
        sb.append(letter);
        TrieNode node = root;
        for (int i = sb.length() - 1; i >= 0 && i >= sb.length() - maxLen; i--) {
            int idx = sb.charAt(i) - 'a';
            if (node.children[idx] == null) return false;
            node = node.children[idx];
            if (node.isWord) return true;
        }
        return false;
    }
}

