private TrieNode root;
private String[] words;

public List<List<String>> wordSquares(String[] words) {
    this.words = words;
    root = new TrieNode();
    for (int i = 0; i < words.length; i++) insert(words[i], i);
    List<List<String>> res = new ArrayList<>();
    int n = words[0].length();
    List<String> square = new ArrayList<>();
    for (String w : words) {
        square.add(w);
        backtrack(1, n, square, res);
        square.remove(square.size() - 1);
    }
    return res;
}

private void insert(String w, int index) {
    TrieNode node = root;
    for (char c : w.toCharArray()) {
        int idx = c - 'a';
        if (node.children[idx] == null) node.children[idx] = new TrieNode();
        node = node.children[idx];
        node.indices.add(index);
    }
}

private List<Integer> startsWith(String prefix) {
    TrieNode node = root;
    for (char c : prefix.toCharArray()) {
        int idx = c - 'a';
        if (node.children[idx] == null) return new ArrayList<>();
        node = node.children[idx];
    }
    return node.indices;
}

private void backtrack(int step, int n, List<String> square, List<List<String>> res) {
    if (step == n) {
        res.add(new ArrayList<>(square));
        return;
    }
    StringBuilder prefix = new StringBuilder();
    for (int i = 0; i < step; i++) prefix.append(square.get(i).charAt(step));
    for (int index : startsWith(prefix.toString())) {
        square.add(words[index]);
        backtrack(step + 1, n, square, res);
        square.remove(square.size() - 1);
    }
}

class TrieNode {
    TrieNode[] children = new TrieNode[26];
    boolean isEnd = false;
}

public String replaceWords(List<String> dictionary, String sentence) {
    TrieNode root = new TrieNode();
    for (String r : dictionary) {
        TrieNode node = root;
        for (char c : r.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) node.children[idx] = new TrieNode();
            node = node.children[idx];
        }
        node.isEnd = true;
    }
    String[] words = sentence.split(" ");
    StringBuilder sb = new StringBuilder();
    for (int w = 0; w < words.length; w++) {
        if (w > 0) sb.append(' ');
        sb.append(shortestRoot(words[w], root));
    }
    return sb.toString();
}

private String shortestRoot(String word, TrieNode root) {
    TrieNode node = root;
    for (int i = 0; i < word.length(); i++) {
        int idx = word.charAt(i) - 'a';
        if (node.children[idx] == null) return word;
        node = node.children[idx];
        if (node.isEnd) return word.substring(0, i + 1);
    }
    return word;
}

private static final int HIGH = 15; // 2*10^4 < 2^15

class TrieNode {
    TrieNode[] children = new TrieNode[2];
    int count = 0;
}

public int countPairs(int[] nums, int low, int high) {
    TrieNode root = new TrieNode();
    int result = 0;
    for (int num : nums) {
        result += countSmaller(root, num, high + 1) - countSmaller(root, num, low);
        insert(root, num);
    }
    return result;
}

private void insert(TrieNode root, int num) {
    TrieNode node = root;
    for (int i = HIGH - 1; i >= 0; i--) {
        int bit = (num >> i) & 1;
        if (node.children[bit] == null) node.children[bit] = new TrieNode();
        node = node.children[bit];
        node.count++;
    }
}

// count of already-inserted v with (num ^ v) < limit
private int countSmaller(TrieNode root, int num, int limit) {
    TrieNode node = root;
    int count = 0;
    for (int i = HIGH - 1; i >= 0 && node != null; i--) {
        int numBit = (num >> i) & 1;
        int limitBit = (limit >> i) & 1;
        if (limitBit == 1) {
            if (node.children[numBit] != null) count += node.children[numBit].count; // xor bit 0 < 1
            node = node.children[numBit ^ 1]; // keep prefix equal (xor bit 1)
        } else {
            node = node.children[numBit]; // xor bit must be 0 to stay smaller
        }
    }
    return count;
}
